    @Inject
    public RavensWatchClient(OkHttpClient okHttpClient, Gson gson) {
        this.okHttpClient = okHttpClient;
        this.gson = gson;
    }

    public static class CalendarResponse {
        public List<CalendarEvent> items;
    }

